CREATE TABLE IF NOT EXISTS orders(reference uuid PRIMARY KEY,product_id text NOT NULL,amount_pence integer NOT NULL,currency text NOT NULL,mode text NOT NULL,status text NOT NULL,stripe_session_id text UNIQUE,stripe_subscription_id text,updated_at timestamptz DEFAULT now());CREATE TABLE IF NOT EXISTS webhook_events(event_id text PRIMARY KEY,type text NOT NULL);CREATE TABLE IF NOT EXISTS fulfilment_outbox(order_reference uuid REFERENCES orders(reference),kind text NOT NULL,state text NOT NULL DEFAULT 'pending',PRIMARY KEY(order_reference,kind));